#!/usr/bin/env bash
set -Eeuo pipefail
# Generated from the trainer-provided Nordlicht-VM-Starter-v2 setup, reviewed 2026-11-05.
# Ubuntu HOST only. Installs QEMU in the temporary exercise host and creates a CirrOS guest.
# Reuses only a matching existing release; a mismatched running guest fails the file checks.
# Public teaching files only; no credentials, private trainer files or learner states included.

umask 077

work_dir="$HOME/nordlicht-lab-autostart"
if (( EUID != 0 )); then
  echo "Bitte im Ubuntu-Hostterminal als root ausführen, erkennbar an root@ubuntu."
  exit 1
fi
mkdir -p "$work_dir"
cd "$work_dir"
exec 9>setup.lock
flock -n 9 || { echo "Das Setup läuft bereits in einem anderen Terminal."; exit 1; }
trap 'echo "Setup abgebrochen (Zeile $LINENO). Arbeitsordner: $work_dir" >&2' ERR

for tool in qemu-system-x86_64 qemu-img cloud-localds socat curl; do
  if ! command -v "$tool" >/dev/null; then
    echo "1/4  Installiere QEMU und die Hilfsprogramme ..."
    export DEBIAN_FRONTEND=noninteractive
    apt-get update
    apt-get install -y qemu-system-x86 qemu-utils cloud-image-utils socat curl
    break
  fi
done

# Prüft auch die Kommandozeile, falls eine alte PID inzwischen wiederverwendet wird.
running() {
  local pid
  [[ -r "$1" ]] || return 1
  read -r pid < "$1" || return 1
  [[ "$pid" =~ ^[1-9][0-9]*$ ]] && kill -0 "$pid" 2>/dev/null &&
    [[ -r "/proc/$pid/cmdline" ]] &&
    grep -aqF -- "$2" "/proc/$pid/cmdline"
}

echo "2/4  Bereite die CirrOS-VM vor ..."
if ! running qemu.pid "$work_dir/console.sock"; then
  if [[ ! -s cirros.img ]]; then
    if ! qemu-img check -f qcow2 cirros.img.part >/dev/null 2>&1; then
      curl --fail --location --retry 2 --connect-timeout 15 --max-time 180 \
        https://download.cirros-cloud.net/0.6.3/cirros-0.6.3-x86_64-disk.img -o cirros.img.part
      qemu-img check -f qcow2 cirros.img.part >/dev/null
    fi
    mv cirros.img.part cirros.img
  fi
  if [[ ! -s nordlicht-a-1g.qcow2 ]]; then
    qemu-img create -f qcow2 -F qcow2 -b cirros.img nordlicht-a-1g.qcow2 1G
  fi
  printf '%s\n' '{"instance-id":"nordlicht-a","local-hostname":"nordlicht-a"}' > meta-data
  cat > user-data <<'GUEST'
#!/bin/sh
set -eu
web=/home/cirros/web
mkdir -p "$web"
command -v base64 >/dev/null && command -v tar >/dev/null && command -v sha256sum >/dev/null
