KURSAUSSTELLUNG_ARCHIVE
(cd "$web" && sha256sum -c SHA256SUMS)
chown -R cirros "$web"
chown cirros "$web"

# Der Dienst soll auch nach einem Neustart der VM wieder bereitstehen.
cat > /etc/init.d/S99nordlicht-web <<'INIT'
#!/bin/sh
case "$1" in
  start) su -s /bin/sh -c 'busybox httpd -p 8080 -h /home/cirros/web' cirros ;;
esac
INIT
chmod 755 /etc/init.d/S99nordlicht-web
/etc/init.d/S99nordlicht-web start
GUEST
  cloud-localds seed-nordlicht-a.img user-data meta-data
  rm -f -- "$work_dir/console.sock"
  qemu-system-x86_64 -name nordlicht-a -accel tcg -smp 1 -m 512 \
    -daemonize -display none -monitor none -pidfile "$work_dir/qemu.pid" \
    -chardev "socket,id=serial0,path=$work_dir/console.sock,server=on,wait=off,logfile=$work_dir/cirros.log" \
    -serial chardev:serial0 -device virtio-rng-pci \
    -drive file=nordlicht-a-1g.qcow2,format=qcow2,if=virtio \
    -drive file=seed-nordlicht-a.img,format=raw,if=virtio,readonly=on \
    -nic user,model=virtio-net-pci,restrict=on,net=10.0.2.0/24,dhcpstart=10.0.2.15,hostfwd=tcp:127.0.0.1:8080-10.0.2.15:8080 9>&-
fi

echo "3/4  Warte auf die Website in der VM ..."
vm_ready=false
for (( attempt=0; attempt<90; attempt++ )); do
  if curl -fsS --max-time 2 http://127.0.0.1:8080/ >/dev/null 2>&1; then
    vm_ready=true
    break
  fi
  sleep 2
done
if [[ "$vm_ready" != true ]]; then
  echo "Die VM antwortet noch nicht auf Port 8080. Letzte Startmeldungen:" >&2
  tail -n 20 cirros.log >&2 || true
  exit 1
fi

echo "4/4  Starte den Browserzugang ..."
if ! running socat.pid 'TCP4-LISTEN:8081,bind=0.0.0.0'; then
  nohup socat TCP4-LISTEN:8081,bind=0.0.0.0,reuseaddr,fork TCP4:127.0.0.1:8080 \
    </dev/null >socat.log 2>&1 9>&- &
  echo "$!" > socat.pid
fi
for (( attempt=0; attempt<10; attempt++ )); do
  if running socat.pid 'TCP4-LISTEN:8081,bind=0.0.0.0' &&
      curl -fsS --max-time 2 http://127.0.0.1:8081/ >/dev/null 2>&1; then
    echo "Pruefe alle Ausstellungsdateien ueber den Gast-Webserver ..."
    while read -r expected relative; do
      actual=$(curl -fsS --max-time 10 "http://127.0.0.1:8081/$relative" | sha256sum | cut -d' ' -f1)
      [[ "$actual" == "$expected" ]] || { echo "Dateipruefung fehlgeschlagen: $relative" >&2; exit 1; }
    done <<'KURSAUSSTELLUNG_CHECKS'
