    echo "FERTIG. Die gepruefte Kursausstellung wird von nordlicht-a ueber Port 8081 ausgeliefert."
    if [[ -r /etc/killercoda/host ]]; then
      browser_url=$(sed -e 's/PORT/8081/g' -e 's/-port\./-8081./I' /etc/killercoda/host)
      if [[ "$browser_url" == https://*-8081.* ]]; then
        printf 'Website im Browser: %s\n' "$browser_url"
      fi
    fi
    echo "In Killercoda könnt ihr die Website auch über Traffic / Ports → 8081 öffnen."
    echo 'VM-Konsole: socat STDIO,rawer,escape=0x1d UNIX-CONNECT:"$HOME/nordlicht-lab-autostart/console.sock"'
    exit 0
  fi
  sleep 1
done
echo "Der Browserzugang auf Port 8081 ist fehlgeschlagen. Meldungen:" >&2
cat socat.log >&2
exit 1
